var EXAMS_BASE = [{"id": "g6-p1", "grado": "6.°", "grupos": ["6-1", "6-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Anatomía del movimiento (Grado 6.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 30, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "El rollo adelante: un movimiento por fases", "instruccion": "(Responda las preguntas 1 a 13 con base en el siguiente texto.)", "cuerpo": "El rollo adelante es un giro del cuerpo sobre una colchoneta. Se realiza en cuatro fases seguidas. En la primera, el estudiante se agrupa: flexiona las rodillas, baja las caderas y acerca el mentón al pecho. En la segunda, apoya firmemente las palmas de las manos sobre la colchoneta, separadas al ancho de los hombros. En la tercera, empuja con las piernas y rueda sobre la parte alta de la espalda; la nuca nunca debe tocar la colchoneta, porque el cuello podría lesionarse. En la cuarta fase recupera la posición: el cuerpo agrupado rueda hasta quedar de pie, sin usar las manos. El secreto de un buen rollo no está en la fuerza, sino en el orden correcto de los apoyos y en mantener el cuerpo agrupado."}, {"id": 2, "titulo": "El rollo atrás y el cuidado del cuello", "instruccion": "(Responda las preguntas 14 a 25 con base en el siguiente texto.)", "cuerpo": "El rollo atrás es el movimiento contrario: el cuerpo gira hacia atrás sobre la colchoneta. Para hacerlo con seguridad, el estudiante coloca las manos junto a los hombros, con las palmas hacia arriba y los dedos apuntando hacia atrás. Al rodar, esas manos se apoyan en la colchoneta y empujan el suelo para levantar la cadera y proteger el cuello, de modo que el peso no caiga sobre la cabeza. Si un estudiante siente dolor en el cuello al terminar, es señal de que no empujó con las manos a tiempo. Para mejorar, el profesor pide llevar una bitácora: un cuaderno donde cada estudiante anota lo que observa de su movimiento y los errores que corrige clase a clase."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Sobre qué superficie se realiza el rollo adelante?", "opciones": {"A": "Sobre el pasto", "B": "Sobre una tabla de madera", "C": "Sobre arena", "D": "Sobre una colchoneta"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántas fases seguidas tiene el rollo adelante?", "opciones": {"A": "Dos", "B": "Tres", "C": "Cinco", "D": "Cuatro"}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "En la primera fase de agrupamiento, ¿hacia dónde se acerca el mentón?", "opciones": {"A": "Hacia el pecho", "B": "Hacia el hombro", "C": "Hacia la rodilla", "D": "Hacia atrás"}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cómo deben estar separadas las palmas al apoyarlas en la colchoneta?", "opciones": {"A": "Al ancho de los hombros", "B": "Muy juntas", "C": "Al ancho de las caderas", "D": "Lo más lejos posible"}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué parte del cuerpo NUNCA debe tocar la colchoneta durante el rollo adelante?", "opciones": {"A": "La espalda", "B": "Las manos", "C": "Los pies", "D": "La nuca"}}, {"n": 6, "seccion": 1, "competencia": "Literal", "enunciado": "En la tercera fase, ¿sobre qué parte del cuerpo se rueda?", "opciones": {"A": "Sobre la cabeza", "B": "Sobre la parte alta de la espalda", "C": "Sobre las rodillas", "D": "Sobre el abdomen"}}, {"n": 7, "seccion": 1, "competencia": "Literal", "enunciado": "Al terminar la cuarta fase, el estudiante queda:", "opciones": {"A": "De pie", "B": "Acostado", "C": "Sentado", "D": "Arrodillado"}}, {"n": 8, "seccion": 1, "competencia": "Literal", "enunciado": "En la recuperación, ¿debe usar las manos para levantarse?", "opciones": {"A": "Sí, siempre", "B": "Solo una mano", "C": "No", "D": "Solo si se cansa"}}, {"n": 9, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, “agruparse” significa:", "opciones": {"A": "Separarse del grupo", "B": "Recoger el cuerpo juntando rodillas y mentón", "C": "Correr en fila", "D": "Estirar todo el cuerpo"}}, {"n": 10, "seccion": 1, "competencia": "Lexical", "enunciado": "La palabra “nuca” se refiere a:", "opciones": {"A": "La parte de atrás del cuello", "B": "La punta del pie", "C": "La palma de la mano", "D": "La rodilla"}}, {"n": 11, "seccion": 1, "competencia": "Inferencial", "enunciado": "Según el texto, ¿por qué la nuca no debe tocar la colchoneta?", "opciones": {"A": "Porque ensucia el cabello", "B": "Porque se pierde el equilibrio del grupo", "C": "Porque el cuello podría lesionarse", "D": "Porque la colchoneta se daña"}}, {"n": 12, "seccion": 1, "competencia": "Inferencial", "enunciado": "Si un estudiante hace el rollo con mucha fuerza pero desordena los apoyos, probablemente:", "opciones": {"A": "El movimiento saldrá mal, porque el secreto está en el orden y no en la fuerza", "B": "Hará un rollo perfecto", "C": "Rodará más rápido y mejor", "D": "No necesitará agruparse"}}, {"n": 13, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un compañero mantiene las piernas estiradas y la cabeza levantada al rodar. Según el texto, el consejo correcto es:", "opciones": {"A": "Mantenerse agrupado y acercar el mentón al pecho", "B": "Estirar más las piernas", "C": "Apoyar la nuca con fuerza", "D": "Hacerlo sin colchoneta"}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Hacia dónde gira el cuerpo en el rollo atrás?", "opciones": {"A": "Hacia adelante", "B": "Hacia un lado", "C": "Hacia atrás", "D": "En círculo"}}, {"n": 15, "seccion": 2, "competencia": "Literal", "enunciado": "¿Dónde se colocan las manos para empezar el rollo atrás?", "opciones": {"A": "Sobre las rodillas", "B": "Detrás de la cadera", "C": "Junto a los hombros", "D": "Sobre la cabeza"}}, {"n": 16, "seccion": 2, "competencia": "Literal", "enunciado": "¿Hacia dónde apuntan los dedos al colocar las manos?", "opciones": {"A": "Hacia adelante", "B": "Hacia atrás", "C": "Hacia afuera", "D": "Hacia el pecho"}}, {"n": 17, "seccion": 2, "competencia": "Literal", "enunciado": "¿Con qué orientación van las palmas de las manos?", "opciones": {"A": "Hacia abajo", "B": "De lado", "C": "Cerradas en puño", "D": "Hacia arriba"}}, {"n": 18, "seccion": 2, "competencia": "Literal", "enunciado": "¿Para qué empujan las manos el suelo al rodar?", "opciones": {"A": "Para ir más despacio", "B": "Para tocar la cabeza", "C": "Para levantar la cadera y proteger el cuello", "D": "Para detener el giro"}}, {"n": 19, "seccion": 2, "competencia": "Inferencial", "enunciado": "Si un estudiante siente dolor en el cuello al terminar el rollo atrás, el texto permite deducir que:", "opciones": {"A": "No empujó con las manos a tiempo", "B": "Empujó demasiado con las manos", "C": "Agrupó bien el cuerpo", "D": "Usó una colchoneta muy blanda"}}, {"n": 20, "seccion": 2, "competencia": "Literal", "enunciado": "¿Qué herramienta pide el profesor para registrar las observaciones?", "opciones": {"A": "Un cronómetro", "B": "Una cámara", "C": "Una bitácora o cuaderno", "D": "Una regla"}}, {"n": 21, "seccion": 2, "competencia": "Literal", "enunciado": "Según el texto, ¿qué se anota en la bitácora?", "opciones": {"A": "Las tareas de otras materias", "B": "Lo que se observa del movimiento y los errores que se corrigen", "C": "El nombre de los compañeros", "D": "Los resultados de un partido"}}, {"n": 22, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, “bitácora” es:", "opciones": {"A": "Un tipo de colchoneta", "B": "Un cuaderno de registro", "C": "Una posición del cuerpo", "D": "Un aparato de gimnasia"}}, {"n": 23, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué es importante que el peso no caiga sobre la cabeza?", "opciones": {"A": "Porque se despeina", "B": "Porque se rueda más lento", "C": "Porque lo exige el reglamento", "D": "Porque protege el cuello de lesiones"}}, {"n": 24, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un estudiante quiere mejorar su rollo atrás clase a clase. Según el texto, lo más útil es:", "opciones": {"A": "Hacerlo cada vez con más fuerza", "B": "Anotar en la bitácora sus errores y correcciones", "C": "Evitar usar las manos", "D": "Apoyar la cabeza primero"}}, {"n": 25, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la idea principal que comparten los dos textos?", "opciones": {"A": "Que los rollos son peligrosos y no deben practicarse", "B": "Que solo importa la fuerza de las piernas", "C": "Que la bitácora reemplaza la práctica", "D": "Que un buen rollo depende del orden de los apoyos y del cuidado del cuello, más que de la fuerza"}}]}, {"id": "g7-p1", "grado": "7.°", "grupos": ["7-1", "7-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Evolución de los aparatos gimnásticos (Grado 7.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 30, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "De la madera a la fibra: la evolución de los aparatos", "instruccion": "(Responda las preguntas 1 a 13 con base en el siguiente texto.)", "cuerpo": "En el siglo XIX, los primeros aparatos de gimnasia se fabricaban con materiales sencillos y rígidos: madera para las barras y los potros, hierro para las estructuras y cuero para las superficies de apoyo. Eran resistentes, pero muy duros: al caer sobre ellos, el cuerpo del gimnasta recibía todo el golpe, porque el material no cedía. Con el paso del tiempo, y sobre todo a mediados del siglo XX, se incorporaron materiales nuevos, como la fibra de vidrio y las espumas. Estos materiales cambiaron el deporte, porque permiten la restitución elástica: el aparato se deforma un poco al recibir el peso y luego devuelve parte de esa energía, como un resorte. Así, la barra fija flexiona y ayuda al giro, y las pistas amortiguan la caída. Gracias a esta evolución, hoy los gimnastas ejecutan movimientos más altos y más seguros que los de hace cien años."}, {"id": 2, "titulo": "Medidas iguales para todos: normalización, equidad y seguridad", "instruccion": "(Responda las preguntas 14 a 25 con base en el siguiente texto.)", "cuerpo": "Para que una competencia sea justa, todos los gimnastas deben usar aparatos idénticos. De eso se encarga la Federación Internacional de Gimnasia (FIG), que fija con exactitud las dimensiones de cada implemento: la altura de la barra, el grosor de las colchonetas y hasta la tensión de los cables. Esta normalización tiene un doble propósito. Por un lado, garantiza la equidad: si un atleta compitiera con una barra más baja o una pista más elástica, tendría una ventaja injusta sobre los demás. Por otro lado, protege la seguridad: una medida mal calculada podría provocar caídas y lesiones graves. Si la federación dejara de regular estas medidas, cada torneo usaría aparatos distintos y los resultados no podrían compararse. Por eso, en clase, cada estudiante lleva una bitácora donde registra las medidas observadas y las relaciona con la seguridad del movimiento."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Con qué materiales se fabricaban los primeros aparatos en el siglo XIX?", "opciones": {"A": "Madera, hierro y cuero", "B": "Fibra de vidrio y espuma", "C": "Plástico y goma", "D": "Aluminio y tela"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿cómo eran esos primeros aparatos?", "opciones": {"A": "Blandos y elásticos", "B": "Resistentes pero muy duros", "C": "Livianos y flexibles", "D": "Frágiles y baratos"}}, {"n": 3, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuándo se incorporaron materiales como la fibra de vidrio y las espumas?", "opciones": {"A": "A comienzos del siglo XIX", "B": "En la Edad Media", "C": "En el año 2000", "D": "A mediados del siglo XX"}}, {"n": 4, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, “rígido” significa:", "opciones": {"A": "Que se dobla con facilidad", "B": "Que es muy liviano", "C": "Que rebota siempre", "D": "Que es duro y no cede"}}, {"n": 5, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿qué permite la restitución elástica?", "opciones": {"A": "Que el aparato se rompa", "B": "Que el gimnasta pese menos", "C": "Que el aparato devuelva parte de la energía", "D": "Que el material no se deforme nunca"}}, {"n": 6, "seccion": 1, "competencia": "Lexical", "enunciado": "La “restitución elástica” se compara en el texto con:", "opciones": {"A": "Un resorte", "B": "Un martillo", "C": "Una piedra", "D": "Un cuchillo"}}, {"n": 7, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué en el siglo XIX el cuerpo del gimnasta recibía todo el golpe al caer?", "opciones": {"A": "Porque los gimnastas eran más débiles", "B": "Porque no existían las reglas", "C": "Porque saltaban desde más alto", "D": "Porque el material rígido no cedía"}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "Se puede deducir que la fibra de vidrio y las espumas hicieron el deporte:", "opciones": {"A": "Más peligroso", "B": "Más lento", "C": "Más alto y más seguro", "D": "Más aburrido"}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un gimnasta salta sobre una pista moderna con restitución elástica. Comparado con una superficie rígida del siglo XIX, lo más probable es que:", "opciones": {"A": "Salte más alto y amortigüe mejor la caída", "B": "Salte más bajo y se lastime más", "C": "No note ninguna diferencia", "D": "El aparato absorba toda su energía"}}, {"n": 10, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el texto dice que la barra fija “ayuda al giro”?", "opciones": {"A": "Porque es de madera", "B": "Porque es más pesada", "C": "Porque flexiona y devuelve energía al gimnasta", "D": "Porque no se deforma"}}, {"n": 11, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, ¿qué recibía todo el golpe al caer sobre un aparato rígido?", "opciones": {"A": "Solo las manos", "B": "El cuerpo del gimnasta", "C": "La estructura de hierro", "D": "El suelo del gimnasio"}}, {"n": 12, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Cuál es la idea principal del Texto 1?", "opciones": {"A": "Los aparatos antiguos eran mejores", "B": "La fibra de vidrio es peligrosa", "C": "La madera devuelve energía", "D": "La evolución de los materiales hizo la gimnasia más alta y segura"}}, {"n": 13, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un compañero afirma: “Antes los aparatos eran mejores porque eran más resistentes”. Según el texto, esa idea es:", "opciones": {"A": "Correcta, porque resistente es igual a seguro", "B": "Discutible, porque ser resistente no evitaba los golpes al no ceder", "C": "Verdadera, porque hoy los aparatos se rompen", "D": "Imposible de evaluar con el texto"}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Qué organización fija las dimensiones de los aparatos?", "opciones": {"A": "El colegio", "B": "Cada entrenador", "C": "Los jueces de cada torneo", "D": "La Federación Internacional de Gimnasia (FIG)"}}, {"n": 15, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál de estas medidas regula la FIG, según el texto?", "opciones": {"A": "El color del uniforme", "B": "La altura de la barra", "C": "El nombre del gimnasta", "D": "La música del ejercicio"}}, {"n": 16, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, “normalización” se refiere a:", "opciones": {"A": "Hacer que algo sea normal o común", "B": "Fijar medidas iguales para todos", "C": "Volver a la normalidad tras una lesión", "D": "Calificar a los atletas"}}, {"n": 17, "seccion": 2, "competencia": "Literal", "enunciado": "¿Cuál es el doble propósito de regular las medidas?", "opciones": {"A": "Rapidez y espectáculo", "B": "Economía y publicidad", "C": "Equidad y seguridad", "D": "Altura y peso"}}, {"n": 18, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué competir con una barra más baja daría una ventaja injusta?", "opciones": {"A": "Porque no todos tendrían las mismas condiciones", "B": "Porque se vería más bonito", "C": "Porque la barra pesaría menos", "D": "Porque el atleta sería más alto"}}, {"n": 19, "seccion": 2, "competencia": "Inferencial", "enunciado": "Si la federación dejara de regular las medidas, ¿qué pasaría con los resultados?", "opciones": {"A": "Serían más justos", "B": "Mejorarían para todos", "C": "No podrían compararse entre torneos", "D": "No cambiarían en nada"}}, {"n": 20, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un organizador quiere que su torneo sea justo. Según el texto, lo primero que debe asegurar es:", "opciones": {"A": "Buena música", "B": "Que todos los aparatos cumplan las medidas de la FIG", "C": "Más público", "D": "Premios costosos"}}, {"n": 21, "seccion": 2, "competencia": "Inferencial", "enunciado": "Una medida mal calculada, según el texto, podría causar:", "opciones": {"A": "Caídas y lesiones graves", "B": "Mejores marcas", "C": "Más equidad", "D": "Menos entrenamiento"}}, {"n": 22, "seccion": 2, "competencia": "Literal", "enunciado": "¿Qué registra el estudiante en la bitácora?", "opciones": {"A": "Los resultados de fútbol", "B": "Las tareas de matemáticas", "C": "Las medidas observadas y su relación con la seguridad", "D": "Los nombres del público"}}, {"n": 23, "seccion": 2, "competencia": "Aplicación", "enunciado": "Dos gimnastas compiten, pero uno usa una pista más elástica. Según el texto, el juez debería:", "opciones": {"A": "Exigir que ambas pistas cumplan la misma norma", "B": "Permitirlo, porque es más divertido", "C": "Subir la puntuación al que salte más", "D": "Ignorar la diferencia"}}, {"n": 24, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál afirmación resume mejor la idea del Texto 2?", "opciones": {"A": "Las medidas iguales le quitan emoción al deporte", "B": "Cada torneo debería usar aparatos diferentes", "C": "La seguridad no depende de las medidas", "D": "Normalizar las medidas hace la competencia justa y segura"}}, {"n": 25, "seccion": 2, "competencia": "Inferencial", "enunciado": "Uniendo los dos textos, se puede concluir que:", "opciones": {"A": "Tanto la evolución de los materiales como la normalización de las medidas buscan un deporte más seguro y justo", "B": "Los materiales y las medidas no influyen en el deporte", "C": "La gimnasia era mejor en el siglo XIX", "D": "La bitácora reemplaza a la federación"}}]}, {"id": "g8-p1", "grado": "8.°", "grupos": ["8-1", "8-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Análisis táctico: baloncesto y voleibol (Grado 8.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 30, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Biomecánica y solución espacial en la invención del baloncesto", "instruccion": "(Responda las preguntas 1 a 6 con base en el siguiente texto.)", "cuerpo": "Durante el invierno de 1891 en Springfield, Massachusetts, el Dr. James Naismith se enfrentó a un dilema pedagógico y biomecánico: cómo mantener la condición física de sus estudiantes en un espacio cerrado sin replicar la violencia de deportes de exterior como el rugbi o el fútbol americano. Naismith comprendió que la agresividad de dichos deportes no dependía de la actitud de los jugadores, sino de la física del juego: al permitir correr sosteniendo el balón, los defensores se veían obligados a detener la inercia del atacante mediante el tacle o el impacto directo. Para neutralizar esta dinámica, Naismith estableció dos premisas revolucionarias. La primera fue disociar el desplazamiento de la posesión estática del balón, obligando al jugador a pasar el balón o botarlo contra el suelo para avanzar, reduciendo la fuerza de inercia en los choques. La segunda fue elevar la meta a 3,05 metros del suelo. Al ubicar el objetivo en un plano vertical elevado, el juego dejó de premiar la fuerza bruta de empuje y pasó a exigir la parábola, la agilidad fina y la precisión motriz."}, {"id": 2, "titulo": "La evolución táctica y la geometría del terreno de juego", "instruccion": "(Responda las preguntas 7 a 12 con base en el siguiente texto.)", "cuerpo": "A lo largo del siglo XX, el baloncesto dejó de ser un simple ejercicio gimnástico para convertirse en un deporte de alta complejidad táctica. La modificación estructural más trascendental ocurrió con la introducción de la línea de tres puntos (adoptada por la NBA en 1979 y por la FIBA en 1984). Antes de esta regla, las defensas se agrupaban masivamente cerca del aro (la zona pintada), congestionando el espacio y convirtiendo el juego en un duelo físico de pívots bajo la canasta. La inclusión del arco perimetral reconfiguró la geometría de la cancha: otorga un punto adicional a los tiros lejanos, lo que obligó a los defensores a salir de la zona restringida para presionar el perímetro, generando espacios libres (“espaciado” o spacing) para las penetraciones. Asimismo, la regla de los 24 segundos para lanzar y la sanción rigurosa de faltas personales tras un límite acumulado transformaron el baloncesto en un deporte de decisiones estratégicas bajo presión temporal, donde la eficiencia en el tiro libre (1 punto) se convirtió en un factor determinante."}, {"id": 3, "titulo": "El paradigma de la no-colisión y los orígenes del Mintonette", "instruccion": "(Responda las preguntas 13 a 18 con base en el siguiente texto.)", "cuerpo": "En 1895, William G. Morgan diseñó en Holyoke, Massachusetts, una disciplina que rompía con el paradigma deportivo de la época: el Mintonette (posteriormente rebautizado como voleibol). Mientras que el fútbol y el baloncesto exigían un despliegue cardiovascular intenso y disputas territoriales directas, Morgan buscaba una alternativa para adultos que requería control neuromuscular, trabajo colaborativo y un riesgo nulo de impacto físico interpersonal. La gran innovación de Morgan residió en instalar una red de tenis elevada a 1,98 metros como una barrera insuperable para los cuerpos, pero permeable para el balón. Al segmentar el terreno en dos campos autónomos, erradicó las colisiones entre rivales, desplazando la lucha deportiva de la confrontación física hacia el dominio del tiempo de vuelo de la pelota. El profesor Alfred Halstead sugirió el nombre Volleyball al observar la dinámica fundamental del juego: sostener el balón en una fase aérea continua (in the volley), prohibiendo expresamente la retención o el descanso del esférico sobre las manos."}, {"id": 4, "titulo": "La dinámica de rotación y la especialización táctica moderna", "instruccion": "(Responda las preguntas 19 a 25 con base en el siguiente texto.)", "cuerpo": "El voleibol moderno se rige por un principio de democracia colectiva y versatilidad espacial denominado sistema de rotación. Cada vez que un equipo receptor gana el derecho al saque (recupera el servicio), sus seis jugadores deben desplazarse obligatoriamente una posición en el sentido de las agujas del reloj. Esta regla impide que un jugador se especialice de forma estática en una sola zona, obligando a todos a transitar tanto por la zona de ataque (red) como por la de defensa (zaguera). Para contrarrestar las limitaciones que la rotación impone a la especialización técnica, el voleibol introdujo roles tácticos muy definidos (armador o colocador, central, opuesto y el Líbero, creado en 1998 para optimizar la defensa con indumentaria distinta). Asimismo, la estructura de juego se basa en una cadena táctica de un máximo de tres toques: recepción (defensa), colocación (armado) y remate (ataque). Esta secuencia transforma un impacto defensivo en una agresión ofensiva organizada, donde la precisión del segundo toque determina la efectividad del ataque final."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Inferencial", "enunciado": "A partir de la lectura, se puede inferir que la violencia en los deportes de exterior del siglo XIX era consecuencia principalmente de:", "opciones": {"A": "La falta de un reglamento estricto sobre el comportamiento ético de los atletas.", "B": "La escasa preparación física de los estudiantes durante los meses fríos de invierno.", "C": "La inercia física generada cuando un jugador se desplazaba a alta velocidad reteniendo el balón.", "D": "El uso de superficies duras y espacios reducidos dentro de los gimnasios de la época."}}, {"n": 2, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, el término “disociar” se utiliza para explicar que Naismith buscaba:", "opciones": {"A": "Eliminar la relación directa entre correr libremente y mantener la pelota atrapada en las manos.", "B": "Separar a los jugadores atacantes de los defensores mediante una red física en la mitad.", "C": "Dividir el tiempo de juego en periodos cortos para evitar el agotamiento físico.", "D": "Impedir que los estudiantes practicaran deportes colectivos dentro del gimnasio."}}, {"n": 3, "seccion": 1, "competencia": "Inferencial", "enunciado": "La decisión de ubicar la canasta a 3,05 metros de altura alteró la naturaleza del juego porque:", "opciones": {"A": "Transformó un objetivo basado en la potencia horizontal en un reto de precisión y trayectoria parabólica.", "B": "Obligó a que los equipos contrataran únicamente a jugadores de gran estatura.", "C": "Evitó que los defensores pudieran saltar para bloquear los lanzamientos al aro.", "D": "Permitió que el balón rebotara de forma impredecible en las barandillas del gimnasio."}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un jugador recibe un pase, se queda inmóvil tres segundos analizando la cancha, luego da cuatro pasos sin botar el balón y lanza. Apoyándose en el Texto 1, el árbitro debe:", "opciones": {"A": "Validar la jugada, porque el jugador estuvo inmóvil analizando la cancha antes de avanzar.", "B": "Anular la jugada por avance ilegal, ya que infringió la premisa de no correr con la pelota retenida.", "C": "Sancionar falta personal, porque permanecer tres segundos estático vulnera la agilidad del juego.", "D": "Otorgar dos tiros libres por haber completado la parábola de tiro hacia la canasta elevada."}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la tesis central que sostiene el autor del Texto 1 sobre la invención de Naismith?", "opciones": {"A": "El baloncesto surgió accidentalmente por la falta de canchas de fútbol disponibles en invierno.", "B": "Las 13 reglas originales del baloncesto buscaban únicamente proteger las cestas de duraznos.", "C": "La biomecánica moderna demostró que las cestas elevadas son perjudiciales para la precisión.", "D": "La innovación de Naismith radicó en modificar la estructura del juego para priorizar la destreza motriz sobre el impacto físico."}}, {"n": 6, "seccion": 1, "competencia": "Lexical", "enunciado": "En el Texto 1, la palabra “inercia” se refiere a:", "opciones": {"A": "La actitud agresiva del jugador.", "B": "La tendencia de un cuerpo en movimiento a seguir avanzando.", "C": "El peso del balón de baloncesto.", "D": "La altura a la que está ubicada la canasta."}}, {"n": 7, "seccion": 2, "competencia": "Inferencial", "enunciado": "De acuerdo con el Texto 2, la concentración de defensores cerca del aro antes de 1979 se debía a que:", "opciones": {"A": "El reglamento prohíba que los jugadores tiraran desde fuera del área.", "B": "Los jugadores no tenían fuerza suficiente para lanzar a más de seis metros.", "C": "Todos los tiros de campo valían lo mismo (2 puntos), sin importar la distancia del lanzamiento.", "D": "La regla de los 24 segundos obligaba a tirar apresuradamente desde la zona pintada."}}, {"n": 8, "seccion": 2, "competencia": "Lexical", "enunciado": "La expresión “reconfiguró la geometría de la cancha” hace referencia a que la línea de tres puntos:", "opciones": {"A": "Alteró las medidas externas de las líneas de banda y de fondo.", "B": "Distribuyó a los jugadores en un espacio más amplio, ampliando la distancia entre atacantes y defensores.", "C": "Eliminó la zona de tres segundos obligando a jugar solo en las esquinas.", "D": "Redujo la superficie del terreno para acelerar las transiciones."}}, {"n": 9, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un equipo pierde por 2 puntos a falta de 3 segundos y su entrenador diseña una jugada hacia la esquina perimetral en vez de un tiro cercano al aro. Esta decisión se justifica porque:", "opciones": {"A": "Busca obtener 3 puntos para ganar el partido en lugar de forzar un empate con 2 puntos.", "B": "Un tiro desde la esquina asegura automáticamente la victoria sin riesgo de fallo.", "C": "Las reglas prohíben hacer canastas de 2 puntos en los últimos cinco segundos.", "D": "El tiro libre otorga automáticamente la posesión del balón al equipo atacante."}}, {"n": 10, "seccion": 2, "competencia": "Inferencial", "enunciado": "A partir del Texto 2, el sistema de faltas acumulativas y tiros libres cumple la función de:", "opciones": {"A": "Castigar económicamente a los equipos que cometen infracciones repetidas.", "B": "Desincentivar la violencia defensiva otorgando puntos de alta probabilidad sin oposición.", "C": "Aumentar el tiempo total de juego para permitir el descanso de los titulares.", "D": "Reemplazar la necesidad de utilizar la línea de tres puntos en los minutos finales."}}, {"n": 11, "seccion": 2, "competencia": "Síntesis Intertextual", "enunciado": "Al comparar el Texto 1 y el Texto 2, se puede afirmar que el baloncesto:", "opciones": {"A": "Ha mantenido intactas sus reglas desde 1891 sin modificaciones significativas.", "B": "Requiere indispensablemente pívots altos para dominar el tablero defensivo.", "C": "Prioriza el contacto físico defensivo por encima del tiro de larga distancia.", "D": "Es un deporte cuya evolución ha sido guiada por la modificación de reglas para optimizar el espacio y la técnica."}}, {"n": 12, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un equipo necesita 3 puntos para ganar en la última posesión. Según el Texto 2, la opción coherente es:", "opciones": {"A": "Buscar un tiro libre de 1 punto.", "B": "Intentar un lanzamiento desde detrás del arco de tres puntos.", "C": "Penetrar para una bandeja de 2 puntos.", "D": "Dejar correr los 24 segundos sin lanzar."}}, {"n": 13, "seccion": 3, "competencia": "Inferencial", "enunciado": "Del Texto 1 se infiere que la intención principal de William G. Morgan al crear el Mintonette fue:", "opciones": {"A": "Ofrecer una práctica deportiva inclusiva que eliminara las lesiones del contacto directo.", "B": "Diseñar una disciplina competitiva de alto impacto para deportistas de élite.", "C": "Adaptar las reglas del tenis para jugarlo en canchas de césped durante el verano.", "D": "Demostrar que los deportes de equipo no requerían un balón esférico."}}, {"n": 14, "seccion": 3, "competencia": "Inferencial", "enunciado": "La función de la red elevada a 1,98 metros en los orígenes del voleibol fue:", "opciones": {"A": "Impedir que los jugadores intercambiaran pases dentro del mismo sector.", "B": "Garantizar que solo los jugadores de gran estatura pudieran anotar puntos.", "C": "Reducir la velocidad del balón antes de que tocara el suelo.", "D": "Servir como un obstáculo físico que neutralizaba el choque interpersonal entre competidores."}}, {"n": 15, "seccion": 3, "competencia": "Lexical", "enunciado": "El cambio de “Mintonette” a “Voleibol” propuesto por Halstead se fundamenta en:", "opciones": {"A": "Un homenaje a la ciudad donde se redactaron las reglas internacionales.", "B": "La descripción precisa de la acción de golpear el balón mientras permanece en el aire.", "C": "La necesidad comercial de asociar el deporte con el tenis y el bádminton.", "D": "La obligación de realizar saques de potencia por encima de la red."}}, {"n": 16, "seccion": 3, "competencia": "Aplicación", "enunciado": "Un estudiante atrapa el balón con ambas manos sobre su pecho, observa a sus compañeros y luego lo lanza por encima de la red. Con base en el Texto 1, esta acción representa:", "opciones": {"A": "Una jugada técnica correcta, pues fomenta el trabajo colaborativo.", "B": "Un punto válido si el balón cae dentro del terreno contrario.", "C": "Una falta técnica de retención, ya que vulnera el principio de mantener el balón en fase aérea continua.", "D": "Una rotación obligatoria por haber retenido la pelota más de tres segundos."}}, {"n": 17, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Según la estructura argumentativa del Texto 1, ¿qué define la “lucha deportiva” en el voleibol?", "opciones": {"A": "El dominio técnico del balón en el aire para evitar que toque el propio campo y enviarlo al adversario.", "B": "La capacidad de invadir el campo contrario para bloquear el avance del rival.", "C": "El uso de la fuerza corporal para desplazar a los rematadores enemigos.", "D": "La resistencia para correr continuamente detrás del balón sin detenerse."}}, {"n": 18, "seccion": 3, "competencia": "Lexical", "enunciado": "En el Texto 1, un “paradigma” es:", "opciones": {"A": "Un tipo especial de balón.", "B": "Una posición fija dentro de la cancha.", "C": "Una falta de retención del balón.", "D": "Un modelo o forma establecida de entender algo."}}, {"n": 19, "seccion": 4, "competencia": "Inferencial", "enunciado": "Según el Texto 2, la rotación obligatoria en el sentido de las agujas del reloj busca garantizar:", "opciones": {"A": "Que el equipo con mejores rematadores permanezca siempre en la red.", "B": "Que los partidos concluyan en un tiempo más corto.", "C": "La participación equitativa de todos los jugadores en las distintas zonas y funciones.", "D": "Que el Líbero pueda atacar libremente desde la zona delantera."}}, {"n": 20, "seccion": 4, "competencia": "Aplicación", "enunciado": "Un equipo comete una “falta de posición o rotación” cuando:", "opciones": {"A": "Realiza tres toques seguidos con golpe de antebrazo.", "B": "El balón toca la cinta superior de la red durante el ataque.", "C": "El entrenador hace más de dos sustituciones en el mismo set.", "D": "Un jugador saca sin que el equipo haya cambiado de posición tras recuperar el servicio."}}, {"n": 21, "seccion": 4, "competencia": "Inferencial", "enunciado": "La secuencia de los tres toques (recepción - colocación - remate) demuestra que el voleibol es un deporte donde:", "opciones": {"A": "La fuerza individual del rematador es más importante que la construcción colectiva.", "B": "Se permite que un mismo jugador golpee el balón dos veces seguidas.", "C": "La defensa zaguera no influye en la efectividad del ataque.", "D": "Cada contacto cumple una función encadenada que transforma la defensa en un ataque estructurado."}}, {"n": 22, "seccion": 4, "competencia": "Inferencial", "enunciado": "La creación del Líbero en 1998 representa una solución para:", "opciones": {"A": "Elevar el nivel defensivo y dar estabilidad al equipo sin alterar el principio de la rotación.", "B": "Reemplazar al entrenador en la toma de decisiones dentro de la cancha.", "C": "Permitir que un jugador alto remate exclusivamente desde el fondo.", "D": "Eliminar el límite de tres toques por equipo."}}, {"n": 23, "seccion": 4, "competencia": "Síntesis Intertextual", "enunciado": "Considerando el Texto 1 y el Texto 2 del voleibol, su identidad se fundamenta en:", "opciones": {"A": "El contacto físico constante y la improvisación individual sin reglas de posición.", "B": "El uso exclusivo de la fuerza de remate sin importar la precisión de los pases.", "C": "La ausencia de contacto directo con el rival, combinada con alta coordinación y rotación colectiva.", "D": "La supremacía de la defensa estática sobre la movilidad de los jugadores."}}, {"n": 24, "seccion": 4, "competencia": "Aplicación", "enunciado": "Un equipo defiende, luego un jugador coloca y otro remata (recepción–colocación–remate). Según el Texto 2, esto ilustra:", "opciones": {"A": "Una falta por tres toques del mismo jugador.", "B": "Una rotación en sentido contrario a las agujas del reloj.", "C": "La cadena táctica que convierte la defensa en un ataque organizado.", "D": "El uso indebido del Líbero en la red."}}, {"n": 25, "seccion": 4, "competencia": "Síntesis Intertextual", "enunciado": "Considerando las cuatro lecturas, ¿qué tienen en común el baloncesto y el voleibol según los textos?", "opciones": {"A": "Ambos evolucionaron modificando reglas para organizar el espacio y reducir o eliminar la violencia del contacto.", "B": "Ambos priorizan el choque físico directo entre rivales.", "C": "Ambos se inventaron para jugarse al aire libre en verano.", "D": "Ambos eliminaron el trabajo en equipo."}}]}, {"id": "g9-p1", "grado": "9.°", "grupos": ["9-1", "9-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Análisis reglamentario del fútbol (Grado 9.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 40, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Tres modalidades, tres reglamentos", "instruccion": "(Responda las preguntas 1 a 13 con base en el siguiente texto.)", "cuerpo": "Aunque comparten la esencia de introducir un balón en la portería contraria con los pies, el fútbol de campo, el fútbol sala (futsal) y el fútbol de salón poseen identidades normativas, dimensiones y entes rectores diferenciados. El fútbol tradicional es gobernado por la FIFA: se juega en canchas de césped de gran escala (100 m x 64 m en promedio), compiten 11 jugadores por equipo y el balón avanza principalmente por rebote aéreo y distancias largas; el fuera de juego (offside) es una regla táctica crucial. El fútbol sala, también regulado por la FIFA, se disputa en coliseos cubiertos sobre madera o PVC de 40 m x 20 m. En él juegan 5 contra 5, el balón es de tamaño reducido y rebote controlado, y los saques de banda y de esquina se ejecutan obligatoriamente con el pie. Una particularidad del fútbol sala FIFA es el uso del tiempo cronometrado deteniendo el reloj cada vez que el esférico sale del campo de juego."}, {"id": 2, "titulo": "El fútbol de salón (AMF) y el posicionamiento táctico", "instruccion": "(Responda las preguntas 14 a 25 con base en el siguiente texto.)", "cuerpo": "En una línea paralela pero institucionalmente ajena se encuentra el fútbol de salón, históricamente gobernado por la AMF (Asociación Mundial de Futsal). Aunque las dimensiones de su rectángulo de juego son similares al futsal FIFA (40 m x 20 m), sus reglas son profundamente distintas: los saques de banda y de esquina se realizan estrictamente con las manos, el balón es aún más pequeño y pesado (de casi nulo rebote), el arquero no puede pasar la mitad de la cancha por vía aérea directa tras un saque de meta, y los jugadores expulsados pueden ser reemplazados tras cumplir una penalización. El posicionamiento táctico también varía: mientras el fútbol tradicional exige roles amplios (laterales, volantes, extremos), las modalidades de salón exigen una rotación constante en posiciones compactas: el Portero, el Líbero o Cierre (defensa central), las Alas (laterales de transición rápida) y el Pívot (atacante de espaldas al arco)."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Literal", "enunciado": "¿Qué organización rige tanto el fútbol tradicional como el fútbol sala?", "opciones": {"A": "La FIFA", "B": "La AMF", "C": "El colegio", "D": "La liga local"}}, {"n": 2, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores por equipo tiene el fútbol tradicional?", "opciones": {"A": "Cinco", "B": "Siete", "C": "Nueve", "D": "Once"}}, {"n": 3, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el fútbol tradicional usa un campo mucho más grande que el fútbol sala?", "opciones": {"A": "Porque tiene menos jugadores", "B": "Porque juegan 11 por equipo y el balón recorre distancias largas", "C": "Porque se juega bajo techo", "D": "Porque el balón no rebota"}}, {"n": 4, "seccion": 1, "competencia": "Literal", "enunciado": "¿Cuántos jugadores por equipo tiene el fútbol sala?", "opciones": {"A": "Siete", "B": "Once", "C": "Cinco", "D": "Seis"}}, {"n": 5, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, “ente rector” significa:", "opciones": {"A": "La organización que gobierna y regula el deporte", "B": "El capitán del equipo", "C": "El árbitro principal", "D": "El estadio donde se juega"}}, {"n": 6, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el fuera de juego (offside) es una regla crucial en el fútbol tradicional?", "opciones": {"A": "Porque hay muy pocos jugadores en cancha", "B": "Porque el reloj se detiene al salir el balón", "C": "Porque el campo amplio y los pases largos favorecen las posiciones adelantadas", "D": "Porque no existe portero"}}, {"n": 7, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el fútbol sala usa un balón de rebote controlado?", "opciones": {"A": "Para que bote lo más alto posible", "B": "Para poder controlarlo en un espacio cerrado y reducido", "C": "Para jugar al aire libre", "D": "Para que pese mucho menos"}}, {"n": 8, "seccion": 1, "competencia": "Inferencial", "enunciado": "El reloj del fútbol sala FIFA se detiene cada vez que el balón sale. Se puede inferir que esto busca:", "opciones": {"A": "Alargar los tiempos de descanso", "B": "Reducir la pérdida de tiempo y dar un tiempo de juego más real", "C": "Confundir a los árbitros", "D": "Acelerar los saques de meta"}}, {"n": 9, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un partido de fútbol sala FIFA, un jugador cobra el saque de banda lanzando el balón con las manos. Según el texto, el árbitro debe:", "opciones": {"A": "Sancionarlo, porque en el fútbol sala el saque se ejecuta con el pie", "B": "Validarlo", "C": "Otorgar un penalti", "D": "Detener el reloj"}}, {"n": 10, "seccion": 1, "competencia": "Aplicación", "enunciado": "Se quiere adecuar un coliseo cubierto para fútbol sala. Según el texto, la superficie adecuada es:", "opciones": {"A": "Césped natural", "B": "Madera o PVC", "C": "Arena", "D": "Tierra"}}, {"n": 11, "seccion": 1, "competencia": "Aplicación", "enunciado": "Un torneo se juega bajo techo en 40 m x 20 m, con 5 jugadores por equipo y saques con el pie. Según el texto, la modalidad es:", "opciones": {"A": "Fútbol tradicional", "B": "Fútbol de salón (AMF)", "C": "Fútbol playa", "D": "Fútbol sala (FIFA)"}}, {"n": 12, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un estudiante afirma: “El fútbol sala y el fútbol tradicional son el mismo deporte con distinto nombre”. Según el texto, esa idea es:", "opciones": {"A": "Imprecisa, porque difieren en dimensiones, número de jugadores y varias reglas", "B": "Correcta, porque ambos usan los pies", "C": "Verdadera, porque los rige la misma FIFA", "D": "Imposible de evaluar con el texto"}}, {"n": 13, "seccion": 1, "competencia": "Literal", "enunciado": "Según el texto, el fuera de juego (offside) es:", "opciones": {"A": "Una falta exclusiva del portero", "B": "Un tipo de saque de esquina", "C": "Una posición de ataque", "D": "Una regla táctica crucial del fútbol tradicional"}}, {"n": 14, "seccion": 2, "competencia": "Literal", "enunciado": "¿Qué organización rige históricamente el fútbol de salón?", "opciones": {"A": "La FIFA", "B": "La FIBA", "C": "La AMF (Asociación Mundial de Futsal)", "D": "El Comité Olímpico"}}, {"n": 15, "seccion": 2, "competencia": "Inferencial", "enunciado": "Aunque comparten dimensiones (40 x 20), el fútbol de salón (AMF) y el fútbol sala (FIFA):", "opciones": {"A": "Son idénticos en sus reglas", "B": "Tienen reglas profundamente distintas", "C": "Usan exactamente el mismo balón", "D": "Comparten el mismo ente rector"}}, {"n": 16, "seccion": 2, "competencia": "Literal", "enunciado": "En el fútbol de salón (AMF), los saques de banda y de esquina se ejecutan:", "opciones": {"A": "Con el pie", "B": "Con la cabeza", "C": "Con las manos", "D": "Con un rebote en la pared"}}, {"n": 17, "seccion": 2, "competencia": "Aplicación", "enunciado": "En un partido de fútbol de salón (AMF), un jugador cobra el saque de banda con el pie. Según el texto, esto es:", "opciones": {"A": "Correcto y válido", "B": "Motivo de expulsión inmediata", "C": "Un gol válido", "D": "Incorrecto, porque en el fútbol de salón el saque se hace con las manos"}}, {"n": 18, "seccion": 2, "competencia": "Inferencial", "enunciado": "El balón del fútbol de salón (AMF), más pequeño, pesado y de casi nulo rebote, exige a los jugadores:", "opciones": {"A": "Menos control técnico", "B": "Mayor control técnico y dominio del balón a ras de piso", "C": "Más juego aéreo", "D": "Menos precisión en el pase"}}, {"n": 19, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un arquero de fútbol de salón (AMF) envía el saque de meta por el aire directamente hasta pasar la mitad de la cancha. Según el texto:", "opciones": {"A": "No está permitido: el arquero no puede pasar la mitad por vía aérea directa tras el saque de meta", "B": "Es una jugada válida y rápida", "C": "Vale doble por la distancia", "D": "Obliga a rotar posiciones"}}, {"n": 20, "seccion": 2, "competencia": "Inferencial", "enunciado": "En el fútbol de salón (AMF), un expulsado puede ser reemplazado tras cumplir una penalización. A diferencia del fútbol tradicional, esto permite que el equipo:", "opciones": {"A": "Quede con un jugador menos todo el partido", "B": "Pierda automáticamente el partido", "C": "No pueda hacer más cambios", "D": "Recupere su número completo de jugadores tras el castigo"}}, {"n": 21, "seccion": 2, "competencia": "Literal", "enunciado": "Según el texto, las posiciones compactas de las modalidades de salón son:", "opciones": {"A": "Laterales, volantes y extremos", "B": "Defensa, medio y delantero", "C": "Portero, líbero o cierre, alas y pívot", "D": "Base, escolta y pívot"}}, {"n": 22, "seccion": 2, "competencia": "Lexical", "enunciado": "En el texto, el “Pívot” de las modalidades de salón es:", "opciones": {"A": "El atacante que juega de espaldas al arco", "B": "El defensa central", "C": "El portero suplente", "D": "El árbitro de mesa"}}, {"n": 23, "seccion": 2, "competencia": "Lexical", "enunciado": "Según el texto, las “Alas” son:", "opciones": {"A": "Los porteros suplentes", "B": "Los delanteros centro", "C": "Los laterales de transición rápida", "D": "Los defensas fijos"}}, {"n": 24, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un equipo de salón necesita un jugador que ataque de espaldas al arco para recibir y girar cerca de la portería rival. Según el texto, debe ubicar a un:", "opciones": {"A": "Pívot", "B": "Cierre", "C": "Ala", "D": "Portero"}}, {"n": 25, "seccion": 2, "competencia": "Síntesis Intertextual", "enunciado": "Uniendo los dos textos, ¿cuál es la conclusión más adecuada sobre las tres modalidades?", "opciones": {"A": "Son deportes sin ninguna relación entre sí", "B": "Todas están regidas por la AMF", "C": "Todas se juegan en césped con 11 jugadores", "D": "Comparten la esencia de anotar con los pies, pero difieren en ente rector, dimensiones, balón, saques y posiciones"}}]}, {"id": "g10-p1", "grado": "10.°", "grupos": ["10-1", "10-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Biomecánica del deporte (Grado 10.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 40, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Biomecánica del tiro en suspensión y transferencia de impulso kinésico", "instruccion": "(Responda las preguntas 1 a 5 con base en el siguiente texto)", "cuerpo": "El tiro en suspensión en el baloncesto moderno representa una compleja integración de cadenas cinéticas motoras. A diferencia del tiro estático de pie, la eficacia del tiro en suspensión reside en la conversión eficiente de la energía cinética horizontal (obtenida durante la carrera o el drible) en energía potencial gravitatoria vertical, alcanzando el punto de suspensión antes de la fase descendente. Desde la perspectiva biomecánica, la secuencia se inicia con una flexión triple simultánea de cadera, rodilla y tobillo (fase de acumulación elástica). Al realizar el salto, los extensores de las extremidades inferiores transfieren el impulso a través del eje axial hacia la cintura escapular. Un error recurrente en atletas en formación es iniciar la extensión de la articulación del codo y la flexión de la muñeca (fase de impulsión del balón) simultáneamente con la fase de ascenso. Biomecánicamente, el momento óptimo de liberación del balón ocurre exactamente en el ápice de la parábola del salto, donde la velocidad vertical es momentáneamente igual a cero. Esto neutraliza la inercia ascendente sobre la trayectoria del balón, permitiendo que la fuerza aplicada dependa exclusivamente del impulso coordinado del miembro superior y del quiebre de muñeca."}, {"id": 2, "titulo": "La física del remate en voleibol: Potencia, torque y momento angular", "instruccion": "(Responda las preguntas 6 a 10 con base en el siguiente texto)", "cuerpo": "El remate es la acción ofensiva por excelencia en el voleibol y demanda una orquestación precisa de las leyes de la física aplicadas al movimiento humano. La fase de batida o carrera de aproximación convierte la energía horizontal en un salto vertical, pero la verdadera generación de potencia en el golpeo al balón proviene de la rotación del tronco y la subsecuente aceleración del segmento hombro-brazo. Durante la fase de preparación en el aire, la hiperextensión del tronco combinada con la abducción del hombro genera un torque muscular en la cadena cruzada anterior (pectoral y abdominales). La liberación de este torque mediante una rápida flexión del tronco crea un efecto de \"fusta\" o látigo donde la energía se transfiere secuencialmente desde el torso hasta la mano. Además, el impacto sobre el balón debe realizarse por encima y ligeramente por delante del centro de gravedad de la pelota, imprimiéndole un efecto de rotación hacia adelante (topspin). Por el principio de Magnus, la rotación hacia adelante genera una diferencia de presión en el aire que empuja el balón hacia abajo con mayor rapidez, garantizando que un remate de alta velocidad descienda antes de sobrepasar la línea de fondo."}, {"id": 3, "titulo": "Análisis comparativo de la desaceleración y frenado: Baloncesto vs. Voleibol", "instruccion": "(Responda las preguntas 11 a 15 con base en el siguiente texto)", "cuerpo": "Tanto en el baloncesto como en el voleibol, el control de la desaceleración constituye la piedra angular de la prevención de lesiones biomecánicas, particularmente de la rotura del ligamento cruzado anterior (LCA). En el baloncesto, los cambios bruscos de dirección (corte o crossover) y las detenciones en un tiempo imponen cargas de cizallamiento altísimas sobre la articulación de la rodilla cuando el vector de fuerza de reacción del suelo (GRF) no se alinea con el centro articular. Por otro lado, en el voleibol, la fase biomecánica de mayor riesgo ocurre durante el aterrizaje posterior al bloqueo o remate. Un aterrizaje rígido con escasa flexión de rodilla (menos de 30 grados) disipa la energía directamente a través de las estructuras óseas y ligamentosas, en lugar de utilizar la musculatura del cuádriceps y los isquiotibiales como amortiguadores dinámicos. La optimización biomecánica en ambos deportes exige el aprendizaje de patrones de absorción de carga que incorporen la flexión profunda de la cadera y la estabilidad en el plano frontal para evitar el valgo dinámico de rodilla (colapso hacia adentro)."}, {"id": 4, "titulo": "Regulación del tiempo de reacción y sistemas de información sensorial", "instruccion": "(Responda las preguntas 16 a 20 con base en el siguiente texto)", "cuerpo": "La toma de decisiones en deportes de conjunto de ritmo rápido como el voleibol y el baloncesto depende de la eficiencia del sistema neuromuscular para procesar estímulos visuales y traducirlos en respuestas motoras biomecánicamente eficientes. Este lapso se conoce como el tiempo de reacción motor. En el voleibol, al recibir un saque flotante o un remate de alta velocidad, el atleta dispone de menos de 400 milisegundos para evaluar la trayectoria, ajustar el centro de gravedad mediante un desplazamiento lateral e interponer la plataforma de antebrazos. En el baloncesto, la anticipación sensorial se evidencia en la lectura de la defensa durante la penetración a la canasta. Los atletas de elite no responden al movimiento final del defensor, sino a micro-pistas biomecánicas como el cambio de orientación de la cadera o el desplazamiento del peso del rival sobre sus talones. Esta capacidad de fijación foveal anticipatoria reduce el tiempo de procesamiento central, permitiendo ejecutar un cambio de dirección o un pase ciego antes de que la cobertura defensiva se consolide. La biomecánica moderna demuestra que el entrenamiento del ojo y la atención selectiva influyen directamente en la fluidez y velocidad de la respuesta técnica."}], "preguntas": [{"n": 1, "enunciado": "Según el Texto 1, el momento ideal para la liberación del balón en el tiro en suspensión ocurre cuando:", "opciones": {"A": "La velocidad vertical del atleta es cero en el punto más alto del salto.", "B": "El jugador inicia el despegue mediante la extensión del tobillo y la rodilla.", "C": "La energía cinética horizontal se transforma completamente en velocidad de carrera.", "D": "La flexión del codo alcanza su máxima amplitud durante el ascenso."}, "competencia": "Literal / Datos explícitos sobre kinésica", "seccion": 1}, {"n": 2, "enunciado": "En el texto, la expresión \"cadena cinética motora\" se refiere a:", "opciones": {"A": "El uso exclusivo de los músculos de la mano para lanzar el balón.", "B": "La fricción que se genera entre el calzado del atleta y la superficie de la cancha.", "C": "La transmisión secuencial de fuerza e impulso muscular entre los diferentes segmentos del cuerpo.", "D": "El tiempo límite reglamentario que tiene un jugador para lanzar a la canasta."}, "competencia": "Lexical / Vocabulario contextual especializado", "seccion": 1}, {"n": 3, "enunciado": "Un tirador que libera el balón mientras aún se encuentra ascendiendo a gran velocidad probablemente sufrirá:", "opciones": {"A": "Una disminución severa en la altura del aro.", "B": "Un cobro inmediato de falta personal por invasión del cilindro del defensor.", "C": "Una alteración en la trayectoria calculada del tiro debido a la inercia ascendente no neutralizada.", "D": "Una pérdida total de la flexión de las articulaciones de la cadera."}, "competencia": "Inferencial / Análisis biomecánico de inercia", "seccion": 1}, {"n": 4, "enunciado": "Del análisis del Texto 1 se deduce que el propósito de la triple flexión (cadera, rodilla, tobillo) es:", "opciones": {"A": "Almacenar energía elástica y generar la potencia requerida para el salto vertical.", "B": "Engañar al árbitro simulando una falta de la defensa.", "C": "Evitar que el defensor pueda realizar una interceptación aérea.", "D": "Mantener la masa corporal en contacto estático permanente con el suelo."}, "competencia": "Inferencial / Causa y función muscular", "seccion": 1}, {"n": 5, "enunciado": "¿Cuál es la idea central que el autor expone respecto a la técnica del tiro en suspensión?", "opciones": {"A": "Requiere únicamente de la potencia ejercida por los bíceps y los pectorales.", "B": "Es una maniobra idéntica en ejecución al tiro libre desde la línea de cobro.", "C": "Depende de la adecuada sincronización biomecánica entre el salto y el instante neutro de liberación.", "D": "Prohíbe el uso de la inercia generada por el drible previo."}, "competencia": "Crítico-Valorativo / Tesis central del texto", "seccion": 1}, {"n": 6, "enunciado": "De acuerdo con el Texto 2, el \"efecto de fusta o látigo\" en el remate de voleibol es generado por:", "opciones": {"A": "La contracción exclusiva de las falanges de la mano en el momento del impacto.", "B": "El contacto directo de los pies con el piso al momento de golpear la pelota.", "C": "La falta de rotación sobre el eje longitudinal de la columna vertebral.", "D": "La liberación secuencial del torque muscular acumulado desde el torso hasta el miembro superior."}, "competencia": "Literal / Transferencia de energía e impulso", "seccion": 2}, {"n": 7, "enunciado": "El principio de Magnus aplicado al efecto topspin (rotación hacia adelante del balón) permite que:", "opciones": {"A": "El balón sufra una fuerza aerodinámica descendente que acelera su caída dentro del campo.", "B": "El balón flote de manera impredecible sin caer al campo contrario.", "C": "El balón pierda toda su velocidad de trayectoria e intente devolverse hacia la red.", "D": "Se anule la exigencia de realizar la carrera de aproximación previa."}, "competencia": "Inferencial / Aplicación del Principio de Magnus", "seccion": 2}, {"n": 8, "enunciado": "Si un atleta de voleibol impacta el balón por debajo de su centro de masa durante un remate, el resultado biomecánico será:", "opciones": {"A": "Un balón que tiende a elevarse o salir del campo por la línea de fondo debido a la falta de fuerza descendente.", "B": "Un remate con trayectoria muy picada hacia la zona de tres metros.", "C": "Un bloqueo efectivo realizado automáticamente por el pasador del propio equipo.", "D": "La anulación inmediata de la rotación del tronco."}, "competencia": "Aplicación / Consecuencia biomecánica de impacto", "seccion": 2}, {"n": 9, "enunciado": "El término \"torque\" en la lectura se refiere a:", "opciones": {"A": "La fuerza pura ejercida por el músculo sin generar rotación articular.", "B": "El momento de fuerza que causa la rotación sobre un eje articular o corporal.", "C": "La distancia que recorre el atleta durante la fase de transición defensiva.", "D": "El tiempo total que permanece el balón en el aire durante la recepción."}, "competencia": "Lexical / Concepto de momento de fuerza (Torque)", "seccion": 2}, {"n": 10, "enunciado": "A partir de la lectura, se deduce que la potencia final de un remate en voleibol no depende únicamente de la fuerza del brazo, sino de:", "opciones": {"A": "La integración fluida de la carrera de aproximación, la rotación del tronco y la aerodinámica del balón.", "B": "La capacidad de mantener la masa corporal estática en el suelo.", "C": "El uso exclusivo de golpeos de antebrazo para atacar sobre la red.", "D": "La altura a la que se encuentre ubicada la línea perimetral de tres puntos."}, "competencia": "Crítico-Valorativo / Síntesis de potencia en remate", "seccion": 2}, {"n": 11, "enunciado": "De acuerdo con el Texto 3, la razón principal por la cual un aterrizaje rígido en voleibol incrementa el riesgo de lesión es:", "opciones": {"A": "Porque la energía de impacto se absorbe dinámicamente mediante el tono del músculo bíceps.", "B": "Porque la falta de flexión articular deriva las cargas de impacto directamente a los huesos y ligamentos.", "C": "Porque incrementa la fuerza de rozamiento entre las manos y el balón de juego.", "D": "Porque invalida el punto obtenido por el equipo durante la jugada de bloqueo."}, "competencia": "Literal / Disipación de cargas e impacto", "seccion": 3}, {"n": 12, "enunciado": "El término \"valgo dinámico de rodilla\" descrito en el texto hace referencia a:", "opciones": {"A": "La alineación perfecta de la pierna en sentido vertical respecto al suelo.", "B": "La extensión completa del tobillo para ganar mayor altura en la batida.", "C": "La rotación externa del hombro al momento de preparar el servicio.", "D": "El colapso o desviación de la rodilla hacia la línea media del cuerpo durante cargas de frenado o aterrizaje."}, "competencia": "Lexical / Terminología biomecánica articular", "seccion": 3}, {"n": 13, "enunciado": "¿Qué diferencia biomecánica en la generación de cargas de riesgo destaca el texto entre el baloncesto y el voleibol?", "opciones": {"A": "El baloncesto genera riesgo en la recepción del saque y el voleibol en los cobros de tiro libre.", "B": "El baloncesto no presenta cargas de impacto sobre la rodilla y el voleibol sí.", "C": "El voleibol exige giros laterales continuos y el baloncesto únicamente desplazamientos verticales.", "D": "El baloncesto presenta alto riesgo en giros y desaceleraciones horizontales, mientras que el voleibol en los aterrizajes verticales."}, "competencia": "Inferencial / Análisis comparativo interdisciplinar", "seccion": 3}, {"n": 14, "enunciado": "Un programa de prevención biomecánica diseñado para deportistas de ambas disciplinas debería enfatizar:", "opciones": {"A": "El entrenamiento de patrones de absorción de carga mediante la flexión de cadera y el control del eje de la rodilla.", "B": "La eliminación total de la flexión de rodilla durante todas las fases de juego.", "C": "La prohibición de realizar saltos en el terreno de juego.", "D": "La utilización de calzado rígido que impida el movimiento del tobillo."}, "competencia": "Aplicación / Diseño de prevención de lesiones", "seccion": 3}, {"n": 15, "enunciado": "Del texto se puede inferir que los músculos cuádriceps e isquiotibiales actúan como:", "opciones": {"A": "Elementos rígidos que bloquean el movimiento articular en el aterrizaje.", "B": "Generadores de carga de cizallamiento sobre la articulación del hombro.", "C": "Disipadores mecánicos de energía que protegen las estructuras pasivas como los ligamentos.", "D": "Músculos secundarios sin relevancia en el control postural del atleta."}, "competencia": "Inferencial / Rol funcional de la musculatura", "seccion": 3}, {"n": 16, "enunciado": "Según el Texto 4, los baloncestistas de élite logran anticipar las acciones de los defensores gracias a:", "opciones": {"A": "La lectura visual de micro-pistas biomecánicas como el cambio de peso o la postura de la cadera del rival.", "B": "La memorización del reglamento oficial de la federación.", "C": "La velocidad pura de carrera sin prestar atención a la posición de la defensa.", "D": "La comunicación verbal constante por parte del cuerpo técnico desde la banca."}, "competencia": "Literal / Lectura de micro-pistas visuales", "seccion": 4}, {"n": 17, "enunciado": "En el contexto de la lectura, el \"tiempo de reacción motor\" se define como:", "opciones": {"A": "La duración total de un partido de voleibol o baloncesto dividida en cuatro cuartos.", "B": "El intervalo entre la recepción de un estímulo sensorial y la finalización del movimiento técnico adaptativo.", "C": "La velocidad máxima a la que se desplaza el balón de aire tras ser golpeado.", "D": "El tiempo de descanso otorgado entre la pérdida de un punto y la ejecución del saque."}, "competencia": "Lexical / Concepto de tiempo de reacción motor", "seccion": 4}, {"n": 18, "enunciado": "En el voleibol, la exigencia biomecánica al recibir un saque de alta velocidad radica en:", "opciones": {"A": "Mantener el centro de gravedad elevado y los brazos cruzados tras la espalda.", "B": "Esperar a que el balón reboté en el suelo antes de intentar el primer toque.", "C": "Ajustar rápidamente el centro de gravedad e interponer la plataforma de contacto en fracciones de segundo.", "D": "Permitir que la pelota toque la red para ganar tiempo de decisión."}, "competencia": "Aplicación / Ajuste postural en voleibol", "seccion": 4}, {"n": 19, "enunciado": "La expresión \"fijación foveal anticipatoria\" se relaciona principalmente con:", "opciones": {"A": "El uso de la fuerza explosiva en los músculos gemelos.", "B": "El mantenimiento del equilibrio sobre una sola pierna durante un lanzamiento libre.", "C": "La prevención de fracturas en los segmentos óseos de los dedos.", "D": "La capacidad del sistema visual para enfocar pistas clave antes de que ocurra la acción principal."}, "competencia": "Inferencial / Percepción e información sensorial", "seccion": 4}, {"n": 20, "enunciado": "Al integrar la información del Texto 3 y del Texto 4, se concluye que el rendimiento óptimo en deportes de conjunto exige:", "opciones": {"A": "Fuerza muscular aislada sin ningún tipo de control perceptivo o visual.", "B": "Una interacción perfecta entre el procesamiento sensorial anticipatorio y la ejecución biomecánica segura y potente.", "C": "El abandono de las reglas de juego en favor del contacto físico directo.", "D": "Depender únicamente de la intuición sin realizar entrenamiento técnico o biomecánico."}, "competencia": "Síntesis Intertextual / Integración de conceptos", "seccion": 4}, {"n": 21, "seccion": 1, "competencia": "Aplicación / Transferencia", "enunciado": "Un jugador libera el balón cuando todavía va subiendo, antes del ápice del salto. Según el Texto 1, el efecto biomecánico es:", "opciones": {"A": "El tiro resulta más preciso y potente.", "B": "Se neutraliza por completo la velocidad vertical.", "C": "La inercia ascendente se suma a la trayectoria y altera el tiro.", "D": "El balón adquiere un efecto de retroceso (backspin)."}}, {"n": 22, "seccion": 2, "competencia": "Inferencial / Principio de Magnus", "enunciado": "Según el Texto 2, ¿por qué el efecto topspin ayuda a que un remate potente caiga dentro de la cancha?", "opciones": {"A": "Porque aumenta la altura del salto del rematador.", "B": "Porque, por el principio de Magnus, la diferencia de presión empuja el balón hacia abajo más rápido.", "C": "Porque reduce el torque del tronco durante el golpe.", "D": "Porque frena el balón en el aire antes del impacto."}}, {"n": 23, "seccion": 3, "competencia": "Aplicación / Absorción de carga", "enunciado": "Un voleibolista aterriza tras el bloqueo con la rodilla casi extendida (menos de 30° de flexión). Según el Texto 3, esto es riesgoso porque:", "opciones": {"A": "La musculatura absorbe toda la energía del impacto.", "B": "Elimina por completo el valgo dinámico de rodilla.", "C": "Reduce las cargas sobre el ligamento cruzado anterior.", "D": "La energía se disipa por huesos y ligamentos en lugar de la musculatura."}}, {"n": 24, "seccion": 4, "competencia": "Inferencial / Anticipación", "enunciado": "Según el Texto 4, un baloncestista de élite anticipa la acción del defensor observando principalmente:", "opciones": {"A": "El movimiento final del defensor.", "B": "El marcador y el tiempo restante del partido.", "C": "La estatura y la envergadura del rival.", "D": "Micro-pistas como la orientación de la cadera o el peso sobre los talones."}}, {"n": 25, "seccion": 4, "competencia": "Síntesis Intertextual / Integración", "enunciado": "Integrando los cuatro textos, ¿qué idea general los articula?", "opciones": {"A": "El rendimiento deportivo depende únicamente de la fuerza física.", "B": "El gesto deportivo eficaz integra principios biomecánicos: transferencia de impulso, física del golpeo, absorción de cargas y tiempo de reacción.", "C": "La biomecánica solo es relevante en el voleibol.", "D": "La técnica no influye en la prevención de lesiones."}}]}, {"id": "g11-p1", "grado": "11.°", "grupos": ["11-1", "11-2"], "periodo": "Periodo 1", "titulo": "Evaluación tipo Saber — Gestión de torneos y sistemas de competencia (Grado 11.°)", "area": "Educación Física, Recreación y Deportes", "timeLimitMin": 40, "puntosPorPregunta": 1, "textos": [{"id": 1, "titulo": "Sistemas de competencia: eliminación directa y todos contra todos", "instruccion": "(Responda las preguntas 1 a 9 con base en el siguiente texto.)", "cuerpo": "Diseñar un torneo exige elegir un sistema de competencia. En el sistema de todos contra todos (o liga), cada equipo se enfrenta a todos los demás; el número total de partidos se calcula con la fórmula n(n–1)/2, donde n es el número de equipos. Este sistema premia la regularidad a lo largo de varios partidos y es más justo, pero requiere más tiempo y más encuentros. En la eliminación directa, en cambio, el equipo que pierde queda fuera; para coronar un campeón con n equipos se necesitan n–1 partidos. Es un sistema rápido y emocionante, pero pesa un solo resultado: un mal día puede eliminar a un buen equipo. Los cuadros de clasificación (o fixtures) organizan los cruces; el “sembrado” ubica a los mejores equipos separados para que no se enfrenten en las primeras rondas. Muchos torneos usan un sistema mixto: una fase de grupos de todos contra todos que aporta justicia, seguida de una fase final de eliminación directa que aporta emoción y define rápido al ganador. Elegir bien depende del número de equipos, del tiempo y de las canchas disponibles."}, {"id": 2, "titulo": "Sistemas de juego en el voleibol: 5-1 y 4-2", "instruccion": "(Responda las preguntas 10 a 17 con base en el siguiente texto.)", "cuerpo": "En voleibol, el nombre del sistema indica cuántos atacantes y cuántos armadores (colocadores) hay en la cancha. En el sistema 4-2 hay cuatro atacantes y dos armadores: siempre hay un armador en la zona delantera, lo que hace el juego más sencillo y estable, aunque solo deja dos atacantes disponibles al frente. En el sistema 5-1 hay cinco atacantes y un único armador, que coloca en todas las rotaciones. Cuando ese armador está en la zona zaguera, el equipo ataca con tres jugadores delanteros, lo que vuelve el ataque más potente y variado; cuando está adelante, ataca con dos. El 5-1 es más ofensivo, pero exige un armador muy resistente y versátil, capaz de sostener el sistema durante todo el partido. Como los seis jugadores rotan de forma obligatoria, el sistema elegido debe funcionar en todas las rotaciones. Así, la elección entre 4-2 y 5-1 no es un capricho: equilibra estabilidad y sencillez frente a potencia ofensiva y complejidad, según el nivel del equipo y la calidad del armador."}, {"id": 3, "titulo": "Gestión de proyectos deportivos: el estudiante como líder", "instruccion": "(Responda las preguntas 18 a 25 con base en el siguiente texto.)", "cuerpo": "En el grado undécimo, el estudiante no solo juega: diseña y lidera un proyecto deportivo institucional. Un buen proyecto articula cuatro dimensiones: la deportiva, la logística (espacios, materiales e inscripciones), la normativa (un reglamento claro) y la social (convivencia y resolución de conflictos). Estas dimensiones están conectadas: si falla una —por ejemplo, la logística cuando no hay canchas disponibles—, todo el proyecto se resiente. Para liderarlo, el estudiante asume distintos roles: como promotor convoca y organiza el evento; como árbitro aplica el reglamento con imparcialidad y resuelve los conflictos de forma asertiva; y como dinamizador o director técnico motiva y orienta a los participantes. La evaluación del torneo no depende solo de la opinión: se apoya en la recolección de datos estadísticos que permiten valorar con objetividad la eficacia de los sistemas y la participación. Al final, el estudiante sustenta su gestión: argumenta las decisiones tomadas y evalúa los resultados del evento que lideró."}], "preguntas": [{"n": 1, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, el sistema “todos contra todos” significa que:", "opciones": {"A": "Solo juegan los dos mejores equipos", "B": "Cada equipo se enfrenta a todos los demás", "C": "El equipo que pierde queda eliminado", "D": "Se juega un único partido decisivo"}}, {"n": 2, "seccion": 1, "competencia": "Aplicación", "enunciado": "En un torneo de todos contra todos con 6 equipos, ¿cuántos partidos se juegan en total? [n(n–1)/2]", "opciones": {"A": "15", "B": "6", "C": "12", "D": "30"}}, {"n": 3, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué el sistema de todos contra todos se considera más justo que la eliminación directa?", "opciones": {"A": "Porque dura menos tiempo", "B": "Porque no necesita árbitros", "C": "Porque siempre gana el equipo favorito", "D": "Porque premia la regularidad a lo largo de varios partidos y no un solo resultado"}}, {"n": 4, "seccion": 1, "competencia": "Aplicación", "enunciado": "En una eliminación directa con 8 equipos, ¿cuántos partidos se necesitan para tener un campeón? [n–1]", "opciones": {"A": "Cuatro", "B": "Siete", "C": "Ocho", "D": "Quince"}}, {"n": 5, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un organizador dispone de un solo día y de muchos equipos. ¿Qué sistema es más adecuado y por qué?", "opciones": {"A": "Eliminación directa, porque reduce el número de partidos y define rápido al campeón", "B": "Todos contra todos, porque es más justo aunque tome más tiempo", "C": "Ninguno, porque es imposible organizarlo", "D": "Todos contra todos, porque usa menos canchas"}}, {"n": 6, "seccion": 1, "competencia": "Lexical", "enunciado": "En el texto, el “sembrado” dentro de un cuadro de clasificación busca:", "opciones": {"A": "Sembrar césped en la cancha", "B": "Eliminar primero a los equipos más débiles", "C": "Ubicar a los mejores equipos separados para que no se enfrenten en las primeras rondas", "D": "Sortear el balón inicial"}}, {"n": 7, "seccion": 1, "competencia": "Inferencial", "enunciado": "¿Por qué un sistema mixto (fase de grupos y luego fase final) combina lo mejor de los dos sistemas?", "opciones": {"A": "Porque la fase de grupos aporta justicia y la fase final aporta emoción y rapidez", "B": "Porque elimina por completo el azar", "C": "Porque no requiere ninguna planificación", "D": "Porque utiliza menos equipos"}}, {"n": 8, "seccion": 1, "competencia": "Multidimensional", "enunciado": "Al diseñar un cuadro de clasificación (fixture), el organizador debe considerar al mismo tiempo:", "opciones": {"A": "Únicamente el número de equipos", "B": "Únicamente el estado del clima", "C": "Únicamente el valor de los premios", "D": "El número de equipos, las canchas disponibles, el tiempo y el sistema elegido"}}, {"n": 9, "seccion": 1, "competencia": "Crítico-Valorativo", "enunciado": "Un estudiante afirma: “La eliminación directa siempre premia al mejor equipo”. Según el texto, esta idea es:", "opciones": {"A": "Totalmente correcta", "B": "Verdadera solo cuando hay 8 equipos", "C": "Discutible, porque pesa un solo resultado y un mal día puede eliminar a un buen equipo", "D": "Imposible de evaluar con el texto"}}, {"n": 10, "seccion": 2, "competencia": "Lexical", "enunciado": "En voleibol, el nombre del sistema (por ejemplo, 5-1) indica:", "opciones": {"A": "El marcador final del partido", "B": "Los minutos que dura cada set", "C": "La cantidad de atacantes y de armadores que hay en la cancha", "D": "El número de sets que se juegan"}}, {"n": 11, "seccion": 2, "competencia": "Inferencial", "enunciado": "¿Por qué el sistema 4-2 se considera más sencillo y estable?", "opciones": {"A": "Porque usa seis armadores a la vez", "B": "Porque siempre hay un armador en la zona delantera, lo que simplifica la organización", "C": "Porque no permite atacar", "D": "Porque no exige rotación"}}, {"n": 12, "seccion": 2, "competencia": "Inferencial", "enunciado": "En el sistema 5-1, cuando el único armador está en la zona zaguera, el equipo puede atacar con:", "opciones": {"A": "Un solo atacante", "B": "Ningún atacante", "C": "Únicamente el líbero", "D": "Tres atacantes delanteros, lo que hace el ataque más potente"}}, {"n": 13, "seccion": 2, "competencia": "Crítico-Valorativo", "enunciado": "¿Cuál es la principal ventaja del 5-1 frente al 4-2 y cuál es su costo?", "opciones": {"A": "Es más ofensivo y variado, pero exige un armador muy versátil y resistente", "B": "Es más simple, pero aburrido", "C": "No tiene ninguna ventaja real", "D": "Elimina la necesidad de rotar"}}, {"n": 14, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un entrenador tiene un equipo de principiantes y un solo armador con poca resistencia. Según el texto, le conviene:", "opciones": {"A": "El 5-1, para exigir más al armador", "B": "El 4-2, por su estabilidad y sencillez", "C": "Jugar sin armador", "D": "No rotar a los jugadores"}}, {"n": 15, "seccion": 2, "competencia": "Aplicación", "enunciado": "Un equipo experto tiene un armador excelente y busca el ataque más potente posible. Según el texto, debe elegir:", "opciones": {"A": "El 4-2", "B": "Ningún sistema", "C": "El 5-1", "D": "Quitar a los atacantes"}}, {"n": 16, "seccion": 2, "competencia": "Multidimensional", "enunciado": "El texto señala que el sistema debe funcionar en todas las rotaciones. Esto implica que la decisión táctica depende de:", "opciones": {"A": "Solo la altura de los jugadores", "B": "Solo el color del uniforme", "C": "Solo el tamaño del balón", "D": "La calidad del armador, el nivel del equipo y la exigencia de cada rotación"}}, {"n": 17, "seccion": 2, "competencia": "Síntesis Intertextual", "enunciado": "Relacionando el Texto 1 y el Texto 2, ¿qué tienen en común planificar un torneo y elegir un sistema de juego?", "opciones": {"A": "Nada, son temas totalmente opuestos", "B": "Ambos dependen únicamente del azar", "C": "Ambos eliminan la necesidad de reglas", "D": "Ambos exigen decisiones estratégicas que equilibran ventajas y costos según el contexto"}}, {"n": 18, "seccion": 3, "competencia": "Lexical", "enunciado": "Según el texto, el estudiante que actúa como “promotor” de un proyecto deportivo es quien:", "opciones": {"A": "Solo juega los partidos", "B": "Convoca y organiza el evento", "C": "Narra los partidos al público", "D": "Vende las boletas de entrada"}}, {"n": 19, "seccion": 3, "competencia": "Aplicación", "enunciado": "Según el texto, ¿qué debe incluir un proyecto deportivo bien diseñado?", "opciones": {"A": "Cronograma, logística, reglamentación y evaluación", "B": "Únicamente el marcador de cada partido", "C": "Únicamente los premios del torneo", "D": "Únicamente el nombre del evento"}}, {"n": 20, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "¿Por qué la evaluación del torneo debe apoyarse en datos estadísticos y no solo en opiniones?", "opciones": {"A": "Porque las opiniones no existen", "B": "Porque los datos son más fáciles de inventar", "C": "Porque el reglamento lo prohíbe", "D": "Porque los datos permiten valorar con objetividad la eficacia y la participación"}}, {"n": 21, "seccion": 3, "competencia": "Multidimensional", "enunciado": "El texto afirma que las dimensiones del proyecto están conectadas. Se puede inferir que si falla la logística (no hay canchas):", "opciones": {"A": "Se afectan las demás dimensiones y todo el proyecto se resiente", "B": "No pasa nada y el torneo sigue igual", "C": "Mejora automáticamente la convivencia", "D": "Se reduce la necesidad de reglamento"}}, {"n": 22, "seccion": 3, "competencia": "Aplicación", "enunciado": "Durante el torneo estalla un conflicto entre dos equipos por una jugada. Según el rol descrito, el estudiante-árbitro debe:", "opciones": {"A": "Ignorar el conflicto", "B": "Tomar partido por su propio equipo", "C": "Aplicar el reglamento con imparcialidad y resolver el conflicto de forma asertiva", "D": "Suspender todo el proyecto"}}, {"n": 23, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "Uniendo los tres textos, el estudiante de 11.° demuestra su aprendizaje cuando:", "opciones": {"A": "Solo memoriza las reglas del deporte", "B": "Juega bien pero no organiza nada", "C": "Planifica el sistema de competencia, elige el sistema de juego y lidera la gestión del evento con datos", "D": "Delega toda la organización en el profesor"}}, {"n": 24, "seccion": 3, "competencia": "Crítico-Valorativo", "enunciado": "Un proyecto tuvo un torneo emocionante, pero sin registro de estadísticas ni reglamento claro. Según el texto, su gestión sería:", "opciones": {"A": "Excelente, porque fue emocionante", "B": "Deficiente en gestión, porque faltaron la reglamentación y los datos para evaluar", "C": "Perfecta, porque no hubo conflictos", "D": "No evaluable de ninguna manera"}}, {"n": 25, "seccion": 3, "competencia": "Síntesis Intertextual", "enunciado": "¿Cuál es la idea central que integra las tres lecturas del grado 11.°?", "opciones": {"A": "Organizar y liderar el deporte exige pensamiento sistémico: decidir los sistemas de competencia y de juego, y gestionar el proyecto en todas sus dimensiones", "B": "El deporte se reduce a jugar bien", "C": "Los torneos no necesitan planeación", "D": "El papel del árbitro es innecesario"}}]}];
